float rainHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
vec3 view(vec2 uv){return vrchSampleSource0(clamp(uv,vec2(.001),vec2(.999))).rgb;}
float rainNoise(vec2 p){
 vec2 i=floor(p),f=fract(p);
 f=f*f*(3.0-2.0*f);
 return mix(mix(rainHash(i),rainHash(i+vec2(1.0,0.0)),f.x),mix(rainHash(i+vec2(0.0,1.0)),rainHash(i+vec2(1.0,1.0)),f.x),f.y);
}
// Condensation: a soft disc blur of the scene behind the glass.
// Lights behind the glass spread into soft discs: the same taps also gather highlights.
vec3 fogView(vec2 uv,float radius,vec2 aspect,out vec3 glow){
 vec3 c=view(uv);
 vec3 s=c*.16;
 glow=max(c-vec3(.7),vec3(0.0))*.16;
 for(int i=0;i<6;i++){
  float fi=float(i);
  float a=fi*2.3999632;
  float r=radius*1.6*sqrt((fi+.5)/6.0);
  vec3 v=view(uv+vec2(cos(a),sin(a))*r*aspect);
  s+=v*.14;
  glow+=max(v-vec3(.7),vec3(0.0))*.14;
 }
 return s;
}
// Static drops on a jittered grid with an irregular outline. xy: lens normal, z: presence.
vec3 staticDrop(vec2 p,float cells,float density,float t,float seed){
 vec2 q=p*cells;
 vec2 id=floor(q),f=fract(q)-.5;
 float h=rainHash(id+seed);
 if(h>density)return vec3(0.0);
 vec2 c=(vec2(rainHash(id+seed+3.1),rainHash(id+seed+7.7))-.5)*.5;
 float life=fract(t*.03*(.4+h)+rainHash(id+seed+1.3));
 float grow=smoothstep(0.0,.1,life)*(1.0-smoothstep(.9,1.0,life));
 float k=rainHash(id+seed+5.2);
 float r=(.07+.33*k*k*k)*grow;
 vec2 d=f-c;
 d.y*=1.0+.3*step(0.0,-d.y)*smoothstep(0.0,r,-d.y);
 // The outline below reaches at most 1.15 r, and drops under .02 are skipped: reject early.
 if(r<.02||dot(d,d)>=r*r*1.3225)return vec3(0.0);
 float a=atan(d.y,d.x);
 r*=1.0+.10*sin(3.0*a+h*6.3)+.05*sin(5.0*a+k*11.0);
 vec2 n=d/max(r,1e-4);
 if(dot(n,n)>=1.0||r<.02)return vec3(0.0);
 return vec3(n,1.0);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=fragCoord/iResolution.xy;
 vec2 p=fragCoord/iResolution.y;
 vec2 aspect=vec2(iResolution.y/iResolution.x,1.0);
 float t=vrchPhase_speed();
 float flash=smoothstep(0.0,.9,uParam_thunder);
 float rain=clamp(uParam_rain,0.0,1.0);
 float size=.6+uParam_size*.8;
 // A raised hand wipes a wide band of the glass clear.
 vec2 lh=vec2(uParam_left_x,uParam_left_y),rh=vec2(uParam_right_x,uParam_right_y);
 vec2 dl=(uv-lh)/aspect,dr=(uv-rh)/aspect;
 vec2 ell=vec2(.5,1.0);
 float wr=.12+.08*uParam_wipe;
 float wipe=uParam_wipe*max(smoothstep(.05,.3,lh.y)*smoothstep(wr,wr*.5,length(dl*ell)),smoothstep(.05,.3,rh.y)*smoothstep(wr,wr*.5,length(dr*ell)));
 // Running drops: one lane per column, stick-slip descent, a clear trail that narrows toward the top.
 float cols=9.0/size;
 float cx=p.x*cols;
 float col=floor(cx);
 float ch=rainHash(vec2(col,11.0));
 float lane=step(ch,.15+.55*rain);
 float prog=fract(t*(.035+.05*ch)+ch*7.0);
 prog+=.13*sin(prog*25.1327)/25.1327;
 float headY=1.2-prog*1.45;
 float wob=.10*sin(p.y*7.0+ch*20.0)+.05*sin(p.y*19.0+ch*9.0);
 float lx=(fract(cx)-.5-(ch-.5)*.35-wob)/cols;
 float hr=(.022+.014*ch)*size;
 vec2 hd=vec2(lx,p.y-headY);
 hd.y*=hd.y<0.0?.8:1.35;
 vec2 hn=hd/hr;
 float above=p.y-headY;
 float taper=mix(.7,.25,smoothstep(0.0,.4,above));
 float trail=lane*step(0.0,above)*smoothstep(.4,0.0,above)*smoothstep(hr*taper,hr*taper*.4,abs(lx));
 // Fog: thicker toward the bottom and in slow patches; cleared along trails and wherever a hand wiped.
 float fogPatch=rainNoise(p*2.2+vec2(0.0,t*.01));
 float fogShape=clamp(.72+.45*fogPatch-.25*uv.y+.2*smoothstep(.35,.5,abs(uv.x-.5)),0.0,1.2);
 float clear=max(trail,wipe);
 float fogAmt=clamp(uParam_fog*fogShape,0.0,1.0)*(1.0-clear);
 vec3 sharp=view(uv);
 vec3 glow;
 vec3 soft=fogView(uv,.004+.03*uParam_blur,aspect,glow);
 vec3 glass=mix(sharp,soft,smoothstep(0.0,.35,fogAmt));
 float lum=dot(soft,vec3(.2126,.7152,.0722));
 glass=mix(glass,glass*.78+vec3(.022,.028,.038)+lum*.12,fogAmt*.55);
 glass+=glow*fogAmt*1.8;
 // Mist: countless tiny beads give the condensation its grain.
 vec2 mq=p*260.0/size;
 vec2 mf=fract(mq)-.5-(vec2(rainHash(floor(mq)),rainHash(floor(mq)+4.1))-.5)*.5;
 float bead=step(.45,rainHash(floor(mq)+9.3))*smoothstep(.28,.1,length(mf))*(1.0-clear);
 glass*=1.0-bead*fogAmt*(.12+.1*mf.y*4.0);
 glass+=vec3(.9,.95,1.0)*bead*fogAmt*smoothstep(.12,0.0,length(mf-vec2(-.06,.08)))*.08;
 // Pick the nearest lens: running head, trail beads, then a clustered field of mostly small drops.
 vec3 lens=vec3(0.0);
 if(lane>0.0&&dot(hn,hn)<1.0)lens=vec3(hn,1.0);
 if(lens.z==0.0&&trail>0.0){
  float bc=above*cols*3.2;
  float bid=floor(bc);
  if(rainHash(vec2(col,bid))<.4){
   vec2 bd=vec2(lx,(fract(bc)-.5)/(cols*3.2));
   float br=hr*(.22+.22*rainHash(vec2(bid,col)));
   if(length(bd)<br)lens=vec3(bd/br,1.0);
  }
 }
 float cluster=.5+.5*sin(p.x*3.1+1.7*sin(p.y*2.3))*sin(p.y*2.7-p.x*1.3+.8);
 bool swept=trail>.3;
 if(lens.z==0.0&&!swept)lens=staticDrop(p,9.0/size,(.12+.28*rain)*cluster,t,0.0);
 if(lens.z==0.0&&!swept)lens=staticDrop(p+.37,26.0/size,(.3+.4*rain)*cluster,t*1.3,17.0);
 if(lens.z==0.0&&!swept)lens=staticDrop(p+.71,60.0/size,(.35+.35*rain)*(.4+.6*cluster),t*1.7,31.0);
 if(lens.z>0.0&&wipe>.5)lens=vec3(0.0);
 vec3 c=glass;
 if(lens.z>0.0){
  vec2 n=lens.xy;
  float n2=dot(n,n),nl=sqrt(n2);
  // A water bead is a wide-angle lens: a whole fogPatch of the scene, shrunk and flipped.
  vec2 bend=n*(1.0+.6*n2)*.11;
  vec3 inside=view(uv-bend*aspect);
  // Dark refracted rim, heavier on the upper edge; light gathers at the bottom lip.
  float rim=smoothstep(.55,1.0,nl)*(.55+.35*smoothstep(-.6,.8,n.y));
  float caustic=smoothstep(.55,.95,nl)*smoothstep(.1,-.9,n.y);
  inside=inside*(1.0-rim*.7)+inside*caustic*.45;
  float spot=exp(-dot(n-vec2(-.3,.45),n-vec2(-.3,.45))*70.0);
  float edge=smoothstep(1.0,.88,nl);
  c=mix(c,inside,edge);
  c+=vec3(1.0)*spot*edge*(.3+uParam_glint*.9);
 }
 // A soft shadow under each running head sells the weight of the water.
 float shade=lane*exp(-dot(hd-vec2(0.0,-hr*1.2),hd-vec2(0.0,-hr*1.2))/(hr*hr*.9))*.22;
 c*=1.0-shade*(1.0-wipe);
 c+=vec3(.75,.85,1.0)*flash*(.05+.22*fogAmt);
 fragColor=vec4(max(c,vec3(0.0)),1.0);
}
